package com.frost289.naisiinvoices
data class Product(val id:String="",val productName:String="",val packLabel:String="",val quantity:Double=0.0,val price:Double=0.0,val stockOnHand:Double=0.0)
data class Customer(val id:String="",val name:String="",val phone:String="",val location:String="",val lat:Double?=null,val lng:Double?=null,val active:Boolean=true,val assignedDay:String?=null)
data class LineItem(val qty:Double=1.0,val desc:String="",val price:Double=0.0,val productName:String?=null,val packLabel:String?=null,val packQuantity:Double?=null,val productId:String?=null){val total get()=qty*price}
data class Order(val id:String="",val orderNo:String="",val status:String="",val customerId:String?=null,val customerName:String="",val customerPhone:String="",val customerLocation:String="",val items:List<LineItem> = emptyList(),val notes:String="",val grandTotal:Double=0.0,val createdBy:String="",val createdByEmail:String="",val submittedAtMillis:Long?=null,val approvedAtMillis:Long?=null,val invoicedAtMillis:Long?=null,val deliveredAtMillis:Long?=null)
data class Invoice(val id:String="",val invoiceNo:String="",val date:String="",val customer:String="",val customerId:String?=null,val phone:String="",val location:String="",val terms:String="",val providerPhone:String="",val notes:String="",val items:List<LineItem> = emptyList(),val grandTotal:Double=0.0)
data class Expense(val id:String="",val date:String="",val category:String="",val amount:Double=0.0,val notes:String="",val createdBy:String="",val createdByEmail:String="")
data class Visit(val id:String="",val date:String="",val customerName:String="",val outcome:String="",val reason:String="",val notes:String="")
